sealed interface Payment {
	data class Card(val pan: String) : Payment
	data class Transfer(val iban: String) : Payment
}
class Checkout(private val gateway: PaymentGateway) {
	fun charge(p: Payment) = when (p) {
		is Payment.Card -> gateway.card(p)
		is Payment.Transfer -> gateway.transfer(p)
	}
}
